function installWildTrainers(maps) {
  for (const t of WILD_TRAINERS) {
    const map = maps[t.map];
    if (!map) continue;
    // Idempotent: re-installing (hot reload, a test importing twice) must not double-place anyone.
    if ((map.npcs || []).some(n => n.id === t.id)) continue;
    const npc = {
      id: t.id,
      spriteRole: t.role,
      trainer: t,
      x: t.x,
      y: t.y,
      dir: t.dir || 'down',
      // facing is owned by the trainer AI (spinners rotate, walkers face where they step)
      facingLock: false,
      ai: t.ai,
      // beaten trainers step aside, exactly like Ranger Ilex
      hideAfter: t.flag
    };
    (map.npcs || (map.npcs = [])).push(npc);
  }
  return maps;
}

