// Signature names share verbs ("Tidal Cannon" on six species), so signatures are keyed by
// their whole tail phrase first. Their per-move hue/density still makes each one unique.
const SIGNATURE_MOTIFS = Object.freeze({
  'cinder torrent': 'torrent', 'furnace arc': 'arc', 'solar pyre': 'pyre', 'abyss jet': 'jet',
  'tidal cannon': 'cannon', 'moonwake surge': 'surge', 'oldwood surge': 'surge', 'briar dominion': 'dominion',
  'canopy crash': 'canopy', 'cloudfall': 'cloudfall', 'tempest dive': 'dive', 'skybreaker': 'skybreaker',
  'colony spear': 'spear', 'wingstorm': 'wingstorm', 'carapace crash': 'crash', 'night torrent': 'torrent',
  'umbral collapse': 'collapse', 'gloam rend': 'rend', 'myriad rush': 'rush', 'chitin barrage': 'barrage',
  'astral haunt': 'haunt', 'soulflare': 'soulflare', 'phantom torrent': 'torrent', 'bloom lance': 'lance',
  'glacier fall': 'glacier', 'boreal fang': 'fang', 'crystal tempest': 'blizzard', 'miasma jet': 'jet',
  'toxin deluge': 'deluge', 'acid crown': 'crown', 'dawnfall': 'dawnfall', 'prism nova': 'nova',
  'aurora ray': 'ray', 'abyss chorus': 'chorus', 'eclipse maw': 'maw', 'wayfarer rush': 'wayfarer',
  'echo hammer': 'hammer', 'guardian impact': 'guardian', 'riptide crown': 'crown', 'cyclone wing': 'cyclone',
  'jetstream talon': 'talon', 'noxious torrent': 'noxious', 'runestone crash': 'crash', 'mountain break': 'break',
  'fault hammer': 'hammer', 'starlight crown': 'starlight', 'radiant comet': 'comet', 'venom mortar': 'mortar',
  'valor break': 'valor', 'elder meteor': 'meteor', 'rune comet': 'comet_rune', 'wyrm meteor': 'meteor',
  'flare pounce': 'pounce', 'rootquake': 'rootquake', 'whitefrost lance': 'blizzard', 'monolith drop': 'monolith',
  'crag cannon': 'crag', 'arc nova': 'nova', 'storm circuit': 'circuit', 'lightning crown': 'crown',
  'magma anthem': 'anthem'
});

// Basic physical strikes: the creature dashes, nothing elemental is emitted.
const QUICK_STRIKES = Object.freeze([
  'tackle', 'quickstep', 'struggle', 'coaltap', 'leaftap', 'staticnudge', 'chitintap', 'wisptouch', 'gleamdot', 'scalepulse'
]);

const QUICK_SET = new Set(QUICK_STRIKES);

const LAST_WORD_ALIASES = Object.freeze({
  crosswind: 'crosswind', skybreaker: 'skybreaker', rootquake: 'rootquake', cloudfall: 'cloudfall',
  wingstorm: 'wingstorm', soulflare: 'soulflare', dawnfall: 'dawnfall'
});

function motifKeyFor(moveId, move = {}) {
  const name = String(move.name || moveId).toLowerCase();
  if (move.signature) {
    const tail = name.split(/\s+/).slice(1).join(' ');
    if (SIGNATURE_MOTIFS[tail]) return SIGNATURE_MOTIFS[tail];
    const last = name.split(/\s+/).pop();
    if (SIGNATURE_MOTIFS[last]) return SIGNATURE_MOTIFS[last];
  }
  const words = name.split(/\s+/);
  const last = words[words.length - 1];
  if (LAST_WORD_ALIASES[last]) return LAST_WORD_ALIASES[last];
  if (MOTIFS[last]) return last;
  return 'generic';
}

/**
 * Resolve one move to its complete particle identity.
 * `move` is the MOVES entry ({name,type,power,category,signature}).
 */
function particlePlan(moveId, move = {}) {
  const type = move.type || 'Plain';
  const kit = TYPE_KITS[type] || TYPE_KITS.Plain;
  const motifKey = motifKeyFor(moveId, move);
  const motif = MOTIFS[motifKey] || MOTIFS.generic;
  const quick = QUICK_SET.has(moveId);
  const seed = apHashString(moveId);
  // Each move owns a hue rotation and density factor, so two moves that share a verb
  // and a type (six species know Tidal Cannon) still read as different techniques.
  const hue = Math.round(apNoise(moveId, 1) * 36) - 18;
  const density = 0.78 + apNoise(moveId, 2) * 0.5;
  const phase = apNoise(moveId, 3) * Math.PI * 2;
  const accent = seed % kit.colors.length;
  const colors = kit.colors.map(c => shiftHue(c, hue));
  // Elemental integrity first: a motif keeps its motion identity, but its shapes are
  // filtered down to the ones the move's own element can actually make (a Tide "Crown"
  // is a crown of water, not of light). Moves that share a motion still differ through
  // their palette shift, count and phase.
  const native = kit.shapes;
  let shapePool = motif.shapes.filter(sh => native.includes(sh));
  for (const sh of native) if (!shapePool.includes(sh)) shapePool.push(sh);
  shapePool = shapePool.slice(0, Math.max(2, Math.min(3, motif.shapes.length)));
  const order = shapePool.map((_, i) => (i + accent) % shapePool.length);
  const shapes = order.map(i => shapePool[i]);
  const count = Math.max(4, Math.round(motif.count * density * 0.78 * (quick ? 0.55 : 1)));
  return Object.freeze({
    id: moveId, type, kit, motifKey, motif, quick, seed, hue, density, phase, accent,
    colors, shapes, count,
    spread: motif.spread * (0.9 + apNoise(moveId, 4) * 0.25),
    speed: motif.speed * (0.92 + apNoise(moveId, 5) * 0.2),
    motion: motif.motion
  });
}

/** Stable identity string for a move's particle look (used by QA to prove uniqueness). */
function particleFingerprint(plan) {
  return [plan.motifKey, plan.motion, plan.shapes.join(','), plan.count, plan.colors.join(''), plan.hue, plan.phase.toFixed(3), Math.round(plan.spread * 10), Math.round(plan.speed * 10)].join('|');
}

