/* ===== js/data/creatures.js ===== */
// MONSTERBOUND species catalog. Species definitions are immutable; owned creatures are created below.

const TYPES=['Ember','Tide','Grove','Gale','Spark','Stone','Frost','Glimmer','Shade','Plain','Wyrm','Venom','Swarm','Spirit'];
const TYPE_COLORS={Ember:'#e45a36',Tide:'#438fc5',Grove:'#4f9a59',Gale:'#92c5b5',Spark:'#efc84a',Stone:'#8a7461',Frost:'#8ed5dd',Glimmer:'#c58adc',Shade:'#62547c',Plain:'#bcae8f',Wyrm:'#8f68d8',Venom:'#9b4fc4',Swarm:'#87a83f',Spirit:'#63c9bd'};

// Attack type -> defending type multiplier. Missing entries are neutral.
const TYPE_CHART={
 Ember:{Grove:2,Frost:2,Swarm:2,Tide:.5,Stone:.5,Ember:.5},
 Tide:{Ember:2,Stone:2,Grove:.5,Spark:.5,Tide:.5},
 Grove:{Tide:2,Stone:2,Ember:.5,Frost:.5,Gale:.5,Grove:.5},
 Gale:{Grove:2,Shade:2,Swarm:2,Spark:.5,Stone:.5,Gale:.5},
 Spark:{Tide:2,Gale:2,Stone:0,Grove:.5,Spark:.5},
 Stone:{Ember:2,Gale:2,Spark:2,Swarm:2,Tide:.5,Grove:.5,Stone:.5},
 Frost:{Grove:2,Gale:2,Wyrm:2,Ember:.5,Stone:.5,Frost:.5},
 Glimmer:{Shade:2,Wyrm:2,Spirit:2,Stone:.5,Glimmer:.5},
 Shade:{Glimmer:2,Plain:2,Spirit:2,Shade:.5},
 Plain:{Shade:0,Spirit:0,Stone:.5},
 Wyrm:{Wyrm:2,Ember:.5,Tide:.5,Grove:.5,Spark:.5},
 Venom:{Grove:2,Glimmer:2,Stone:.5,Venom:.5,Spirit:.5},
 Swarm:{Grove:2,Shade:2,Glimmer:2,Ember:.5,Gale:.5,Stone:.5,Swarm:.5},
 Spirit:{Spirit:2,Shade:.5,Glimmer:.5,Plain:0}
};
function typeEffectiveness(attackType,defendingTypes){return defendingTypes.reduce((m,t)=>m*(TYPE_CHART[attackType]?.[t]??1),1)}

const moveSeeds={
 Ember:['Coal Tap','Flicker','Cinder Pounce','Caldera Roar'],Tide:['Dew Dart','Ripple','Rushing Wake','Deluge Crown'],Grove:['Leaf Tap','Root Snare','Briar Rush','Oldwood Oath'],Gale:['Draft Peck','Crosswind','Sky Spiral','Tempest Choir'],Spark:['Static Nudge','Hum Bolt','Arc Dash','Thunder Lattice'],Stone:['Gravel Toss','Fault Jab','Basalt Crash','Mountain Verdict'],Frost:['Chill Pin','Rime Veil','Glacier Claw','Whiteout Bell'],Glimmer:['Gleam Dot','Prism Wink','Aurora Lance','Dawn Chorus'],Shade:['Dusk Touch','Gloom Fold','Umbral Fang','Nightfall Hymn'],Plain:['Tackle','Quick Step','Resolute Bash','Echo Break'],Wyrm:['Scale Pulse','Rune Breath','Astral Talon','Elderstar Descent'],Venom:['Toxin Pin','Acid Veil','Viper Torrent','Miasma Crown'],Swarm:['Chitin Tap','Wing Flurry','Colony Rush','Myriad Eclipse'],Spirit:['Wisp Touch','Soul Current','Phantom Claw','Beyond Bell']
};
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'');
const MOVES={};
for(const [type,names] of Object.entries(moveSeeds))names.forEach((name,i)=>{const powers=[8,13,19,27],accuracy=[100,96,91,84];MOVES[slug(name)]={name,type,power:powers[i],accuracy:accuracy[i],priority:i===0&&type==='Plain'?1:0,pp:[35,25,15,8][i],category:i%2===0?'physical':'special',status:i>=1&&['Ember','Grove','Spark','Frost','Shade','Venom','Spirit'].includes(type)?{name:{Ember:'burn',Grove:'poison',Spark:'paralysis',Frost:'sleep',Shade:'sleep',Venom:'poison',Spirit:'sleep'}[type],chance:i===3?30:15}:null,description:`A ${type.toLowerCase()} technique with ${i<2?'steady':'high'} resonance.`}});
MOVES.guardtone={name:'Guard Tone',type:'Plain',power:0,accuracy:100,priority:0,pp:20,category:'status',effect:{kind:'stat',stat:'defense',stages:1,target:'self'},description:'Raises the user’s defense for this battle.'};
MOVES.mendnote={name:'Mend Note',type:'Glimmer',power:0,accuracy:100,priority:0,pp:10,category:'status',effect:{kind:'heal',ratio:.25},description:'Restores a quarter of maximum health.'};
MOVES.struggle={name:'Struggle',type:'Plain',power:10,accuracy:100,priority:0,pp:999,category:'physical',description:'A desperate attack when no technique remains.'};

// Support techniques (one per learnset slot in the 21-30 band). Each one does something
// different: four different stat stages, a guaranteed poison, and a one-turn ward.
const STATUS_MOVES={
 rallyhymn:{name:'Rallying Roar',type:'Plain',power:0,accuracy:100,priority:0,pp:20,category:'status',effect:{kind:'stat',stat:'attack',stages:1,target:'self'},description:'A bellow that stiffens the user\u2019s nerve and raises its attack.'},
 ironoath:{name:'Bulwark Stance',type:'Stone',power:0,accuracy:100,priority:0,pp:20,category:'status',effect:{kind:'stat',stat:'defense',stages:1,target:'self'},description:'The user plants itself like bedrock and raises its defence.'},
 calmhymn:{name:'Stillwater Guard',type:'Tide',power:0,accuracy:100,priority:0,pp:20,category:'status',effect:{kind:'stat',stat:'specialDefense',stages:1,target:'self'},description:'A flat, glassy calm that raises the user\u2019s special defence.'},
 emberhymn:{name:'Ember Surge',type:'Ember',power:0,accuracy:100,priority:0,pp:20,category:'status',effect:{kind:'stat',stat:'specialAttack',stages:1,target:'self'},description:'The user draws its heat inward and raises its special attack.'},
 wardingveil:{name:'Aegis Field',type:'Glimmer',power:0,accuracy:100,priority:3,pp:10,category:'status',effect:{kind:'protect'},description:'A hard shell of light that turns aside the next attack aimed at the user.'},
 venomveil:{name:'Toxic Spore',type:'Venom',power:0,accuracy:90,priority:0,pp:15,category:'status',effect:{kind:'status',status:{name:'poison',chance:100},target:'foe'},description:'A burst of caustic spores that poisons whatever it settles on.'}
};
Object.assign(MOVES,STATUS_MOVES);
const STATUS_BY_TYPE={Ember:'emberhymn',Tide:'calmhymn',Grove:'ironoath',Gale:'calmhymn',Spark:'emberhymn',Stone:'ironoath',Frost:'calmhymn',Glimmer:'calmhymn',Shade:'venomveil',Plain:'rallyhymn',Wyrm:'ironoath',Venom:'venomveil',Swarm:'venomveil',Spirit:'calmhymn'};
