const MAP_BIOME = Object.freeze({
  fernbrook: 'meadow', whisperleaf: 'grove', mossveil: 'grove', brookhaven: 'shallows',
  granitePass: 'quarry', graniteCave: 'quarry', sunmere: 'shallows', emberfall: 'caldera',
  relicrest: 'prism', underarchive: 'summit', frostmere: 'tundra', stormrest: 'stormfield',
  bloomreach: 'grove', ironroot: 'grove', starfall: 'summit', league: 'prism',
  echoWilds: 'meadow', obsidianTunnel: 'caldera', auroraReach: 'tundra',
  moonstoneTunnel: 'prism', hollowmere: 'mire', basaltTunnel: 'quarry',
  prismport: 'shallows', quartzTunnel: 'tundra', dawnspire: 'prism',
  wyrmwardTrail: 'summit', astralPeaks: 'summit', meteorVault: 'summit',
  aerieSanctuary: 'highland', wyrmSummit: 'summit', ghostTown: 'haunt',
  ghostTower1: 'haunt', ghostTower2: 'haunt', ghostTower3: 'haunt', home: 'meadow', lab: 'meadow',
});

/**
 * Resolve the battlefield for a fight.
 *
 * @param {object} options
 * @param {string} [options.map]        map id the battle starts on
 * @param {string[]} [options.enemyTypes] types of the creature(s) being fought
 * @param {string[]} [options.mapTypes] types the map spawns, used as a tie-breaker
 * @param {string} [options.kind]       wild | trainer | gym | elite | champion | rival
 * @param {string} [options.gymType]    the leader's signature element, if this is a gym
 * @returns {Readonly<object>} a frozen battlefield profile
 */
function battleEnvironment({map = '', enemyTypes = [], mapTypes = [], kind = 'wild', gymType = ''} = {}) {
  const scores = new Map();
  const add = (type, weight) => {
    const biome = TYPE_BIOME[type];
    // Plain is the neutral element: a Plain creature borrows the ground it stands on
    // instead of dragging a meadow everywhere, so it scores almost nothing.
    if (biome) scores.set(biome, (scores.get(biome) || 0) + (type === 'Plain' ? weight * 0.2 : weight));
  };
  // The opponent drives the field: a Spirit fight brings its own fog anywhere.
  enemyTypes.forEach((type, i) => add(type, i === 0 ? 3 : 2));
  if (gymType) add(gymType, 4);
  // The location colours the rest, but never overrules a strong opponent.
  mapTypes.forEach(type => add(type, 1));
  const mapBiome = MAP_BIOME[map];
  if (mapBiome) scores.set(mapBiome, (scores.get(mapBiome) || 0) + 2);
  if (!scores.size) scores.set('meadow', 1);
  let best = null;
  for (const [biome, score] of scores) {
    if (!best || score > best.score || (score === best.score && biomeOrder(biome) < biomeOrder(best.biome))) best = {biome, score};
  }
  const profile = BATTLE_BIOMES[best.biome] || BATTLE_BIOMES.meadow;
  return Object.freeze({
    ...profile,
    biome: profile.id,
    map,
    kind,
    // Trainer battles fight on a groomed field of the same family.
    arena: kind === 'wild' ? 'wild' : 'staged',
  });
}

function biomeOrder(biome) {
  return Object.keys(BATTLE_BIOMES).indexOf(biome);
}

/** Convenience for the battle system: resolve a fight from live encounter data. */
function environmentForBattle({map, enemy, kind, gymType}) {
  const species = enemy ? SPECIES[enemy.species || enemy] : null;
  return battleEnvironment({
    map,
    enemyTypes: species ? species.types : [],
    mapTypes: [],
    kind,
    gymType,
  });
}

