 auralithChoice:{chapter:4,quest:'ancientEcho',stage:4,dialogue:D('Auralith',["EIGHT VOICES CALLED ME. ONE VOICE TRIED TO HOLD THEM ALL.","LITTLE LISTENER—SHOULD PAIN BE ERASED, OR CARRIED TOGETHER?"],{choices:[{label:'Carry it together',value:'together'},{label:'Remember, then rebuild',value:'rebuild'}]}),choiceFlags:{together:'auralithTogether',rebuild:'auralithRebuild'},setFlags:['ancientRestored','championshipUnlocked'],after:'chapter4Epilogue'},
 chapter4Epilogue:{chapter:4,dialogue:D('Dr. Vela',["The eight currents are separating and stabilizing. Wild signals are returning across Echora.","Vale will answer for the cages, but his warning will not be discarded. We build safer bonds by remembering the cost.","The Crown Championship is open, {player}. This time the signal is yours to choose." ])},
 championshipWelcome:{chapter:5,quest:'newChampion',stage:0,trigger:{map:'leagueHall',requires:{flag:'championshipUnlocked'}},once:true,dialogue:D('Champion Seren',["Badges admit strong trainers. What you did below proves something rarer.","Still, the Crown is decided in battle. Four Elite Listeners wait, and then I do.","Touch the central sigil when you are ready. You may leave to prepare." ]),setFlags:['championshipRegistered']},
 eliteOne:{chapter:5,dialogue:D('Elite Tamsin',["I study beginnings. Show me whether your first bond still guides your strongest team." ]),action:{battle:'elite',name:'Elite Tamsin',roster:[['calderion',46],['torrentusk',46],['verdantor',46]],reward:900,arena:{sky:'#d9c9a8',ground:'#765f4b',accent:'#82b56a'},winFlag:'elite1'},afterVictory:'eliteTwo'},
 eliteTwo:{chapter:5,dialogue:D('Elite Quill',["A perfect plan is one turn away from becoming obsolete. Adapt." ]),action:{battle:'elite',name:'Elite Quill',roster:[['tempestag',48],['stormantis',48],['galecrest',48]],reward:950,arena:{sky:'#9fc9d2',ground:'#536f82',accent:'#f2d36a'},winFlag:'elite2'},afterVictory:'eliteThree'},
 eliteThree:{chapter:5,dialogue:D('Elite Dorr',["Conditions reveal character. Recover without surrendering momentum." ]),action:{battle:'elite',name:'Elite Dorr',roster:[['glaciabloom',49],['fungalith',49],['radiamander',49]],reward:1000,arena:{sky:'#c8d8d0',ground:'#596d63',accent:'#b58bd2'},winFlag:'elite3'},afterVictory:'eliteFour'},
 eliteFour:{chapter:5,dialogue:D('Elite Nyx',["Light, shadow, certainty, doubt. Bring all of yourself—or I will find the missing half." ]),action:{battle:'elite',name:'Elite Nyx',roster:[['auroraven',50],['eclipther',50],['veilgeist',50]],reward:1100,arena:{sky:'#2d2947',ground:'#4d405f',accent:'#e0c6ee'},winFlag:'elite4'},afterVictory:'championSeren'},
 championSeren:{chapter:5,dialogue:D('Champion Seren',["I watched your journey through reports, but reports flatten people into victories.","Orin says you listen. Vela says you question. Vale says you made him hear what he feared.","Now let your team tell me who you are." ]),action:{battle:'champion',name:'Champion Seren',roster:[['briarhelm',52],['sonicarab',52],['bastionaut',53],['borealoper',53],['radiamander',54],['wayfaroo',55]],reward:3000,arena:{sky:'#e6e2c4',ground:'#345963',accent:'#f2c14e'},winFlag:'champion'},afterVictory:'championEnding'},
 championEnding:{chapter:5,quest:'newChampion',stage:3,dialogue:D('Champion Seren',["The Crown is yours, Champion {player}.","Not because you never failed, but because every answer left room for another voice." ]),setFlags:['champion'],give:{leagueWrit:1},after:'credits'},
 credits:{chapter:5,dialogue:D('Narration',["Fernbrook rings its smallest bell. Brookhaven answers with its largest.","Across Echora, creatures return to old paths while new safeguards replace the Choir’s cages.","Orin asks for a rematch before the ceremony is over.","MONSTERBOUND: ECHOES OF THE EIGHT — END" ])},
 postgameStart:{chapter:6,quest:'postgame',stage:1,trigger:{map:'echoWilds',requires:{flag:'champion'}},once:true,dialogue:D('Researcher Iona',["Champion, the restored currents uncovered a valley absent from every modern map.","Three resonance motes separated from Auralith during the crisis. Their signals are nearby.","Find them, and we may hear memories older than the League." ]),setFlags:['postgameStarted']},
 postgameShrine:{chapter:6,quest:'postgame',stage:3,dialogue:D('Auralith’s Shrine',["The three motes join the stone. Auralith’s first song fills the valley—not a command, but an invitation.","Advanced Gym rematches and rare Echo migrations are now active." ]),setFlags:['postgameComplete','rematchesUnlocked']},
 orinPost:{chapter:6,dialogue:D('Orin',["Champion is a title. Rival is permanent.","Next time, I’m bringing six partners and no speeches. Probably one speech." ])},
 ionaPost:{chapter:6,dialogue:D('Iona',["Vale’s trial testimony changed regional law: no energy project may isolate an Echo from its bonded voice.","Consequences and useful truth can exist together. History should remember both." ])}
