/* ===== js/data/maps.js ===== */
// Data-driven overworld. Every visible doorway or edge opening has a real destination.


const TILE={GRASS:0,PATH:1,TREE:2,TALL:3,WATER:4,FLOOR:5,COUNTER:6,DOOR:7,FLOWER:8,SOIL:9,CLIFF:10,FENCE:11,WALL:12,CAVE:13,SAND:14,BRIDGE:15,ROCK:16,ROOF:17};
const PASSABLE=new Set([TILE.GRASS,TILE.PATH,TILE.TALL,TILE.FLOOR,TILE.DOOR,TILE.FLOWER,TILE.SOIL,TILE.SAND,TILE.BRIDGE,TILE.CAVE]);
const mk=(id,name,w=36,h=26,fill=TILE.GRASS,theme='meadow')=>({id,name,w,h,theme,tiles:Array.from({length:h},()=>Array(w).fill(fill)),spawns:{},exits:[],npcs:[],objects:[],encounterZones:[]});
const rect=(m,x,y,w,h,t)=>{for(let yy=Math.max(0,y);yy<Math.min(m.h,y+h);yy++)for(let xx=Math.max(0,x);xx<Math.min(m.w,x+w);xx++)m.tiles[yy][xx]=t};
const hline=(m,x,y,w,t)=>rect(m,x,y,w,1,t),vline=(m,x,y,h,t)=>rect(m,x,y,1,h,t);
const border=(m,t=TILE.TREE)=>{hline(m,0,0,m.w,t);hline(m,0,m.h-1,m.w,t);vline(m,0,0,m.h,t);vline(m,m.w-1,0,m.h,t)};
function edgeExit(m,side,at,to,spawn,name,requires=null,blockedText='The way is not open yet.'){
 let x,y;if(side==='west'){x=0;y=at;hline(m,0,y,3,TILE.PATH)}if(side==='east'){x=m.w-1;y=at;hline(m,m.w-3,y,3,TILE.PATH)}if(side==='north'){x=at;y=0;vline(m,x,0,3,TILE.PATH)}if(side==='south'){x=at;y=m.h-1;vline(m,x,m.h-3,3,TILE.PATH)}
 m.exits.push({x,y,to,spawn,name,requires,blockedText,side});
}
function building(m,x,y,w,h,label,to,color='teal'){
 rect(m,x,y,w,h,TILE.WALL);hline(m,x,y,w,TILE.ROOF);hline(m,x,y+1,w,TILE.ROOF);const doorX=x+Math.floor(w/2);m.tiles[y+h-1][doorX]=TILE.DOOR;const outsideSpawn=`outside_${to}`;m.spawns[outsideSpawn]={x:doorX,y:Math.min(m.h-2,y+h),dir:'down'};m.exits.push({x:doorX,y:y+h-1,to,spawn:'entry',name:label,side:'door'});m.objects.push({kind:'buildingLabel',x,y:y+h-1,w,h,doorX,label,color,target:to,badge:GYMS[to]?.badge||null,theme:GYMS[to]?.theme||null,accent:GYMS[to]?.arena?.accent||null,badgeName:GYMS[to]?.badgeName||null,city:GYMS[to]?.city||null,solid:false});
}
function indoor(id,name,kind='home'){
 const m=mk(id,name,20,15,TILE.FLOOR,kind);border(m,TILE.WALL);m.spawns.entry={x:10,y:12,dir:'up'};m.tiles[14][10]=TILE.DOOR;m.exits.push({x:10,y:14,to:null,spawn:null,name:'Outside',side:'south',returnExit:true});
 if(kind==='lab'){rect(m,2,2,5,2,TILE.COUNTER);rect(m,13,2,5,2,TILE.COUNTER);rect(m,7,6,7,1,TILE.COUNTER);m.npcs.push({id:'vela',x:10,y:4},{id:'researcher',x:5,y:6,ambientId:'lab_researcher',homeX:5,homeY:6,wander:true,wanderRadius:2});m.objects.push({kind:'starterOrb',x:8,y:6,index:0,species:'cindercub',accent:'#e76b42',solid:true},{kind:'starterOrb',x:10,y:6,index:1,species:'brookfin',accent:'#4aa7cf',solid:true},{kind:'starterOrb',x:12,y:6,index:2,species:'mossprout',accent:'#66ad63',solid:true},{kind:'labTerminal',x:16,y:5,dialogue:'labConsole',solid:true},{kind:'researchBench',x:3,y:8,solid:true,text:'Samples pulse behind safety glass in carefully labeled trays.'},{kind:'monitorWall',x:14,y:9,solid:false},{kind:'floorLamp',x:2,y:11,solid:true});}
 if(kind==='home'){m.objects.push({kind:'chest',x:3,y:4,id:'homeChest',loot:{hushleafTonic:2},text:'You found two Hushleaf Tonics.',solid:true},{kind:'bed',x:15,y:4,dialogue:'bed',solid:true},{kind:'furnitureTable',x:8,y:7,solid:true},{kind:'shelf',x:3,y:9,solid:true},{kind:'floorLamp',x:17,y:6,solid:true});}
 if(kind==='shop'){
 // Supply Mart floor: a service counter along the back wall, goods on both side walls, a centre
 // display island and a produce stand by the door, so the shop reads as a shop from the entrance.
 rect(m,2,2,16,2,TILE.COUNTER);
 m.npcs.push({id:'merchant',x:10,y:4},{id:'citizen',x:6,y:9,ambientId:'shop_customer',homeX:6,homeY:9,wander:true,wanderRadius:2});
 m.objects.push(
  {kind:'shelf',x:3,y:7,solid:true},{kind:'shelf',x:3,y:9,solid:true},
  {kind:'shelf',x:16,y:7,solid:true},{kind:'shelf',x:16,y:9,solid:true},
  {kind:'monitorWall',x:14,y:4,solid:false},
  {kind:'martCounter',x:10,y:8,solid:true},
  {kind:'martCrate',x:6,y:6,solid:true},{kind:'martCrate',x:13,y:10,solid:true},
  {kind:'furnitureTable',x:10,y:10,solid:true});
}
 if(kind==='center'){rect(m,2,2,16,2,TILE.COUNTER);m.npcs.push({id:'healer',x:10,y:4},{id:'patient',x:5,y:9,ambientId:'center_patient',homeX:5,homeY:9,wander:true,wanderRadius:2});m.objects.push({kind:'terminal',x:15,y:5,dialogue:'storageTerminal',solid:true},{kind:'centerSeat',x:4,y:7,solid:true},{kind:'centerSeat',x:7,y:7,solid:true},{kind:'monitorWall',x:3,y:4,solid:false},{kind:'floorLamp',x:17,y:10,solid:true});}
 if(kind==='gym'){rect(m,3,5,14,1,TILE.FENCE);m.tiles[5][10]=TILE.PATH;m.npcs.push({id:'gymGuide',x:10,y:3});m.objects.push({kind:'sigil',x:10,y:8,dialogue:'gymSigil',solid:true});}
 return m;
}
function setReturn(m,to,x,y){const e=m.exits.find(e=>e.returnExit),destination=MAPS[to],outside=`outside_${m.id}`,spawn=destination?.spawns?.[outside]?outside:'fromInterior';e.to=to;e.spawn=spawn;m.spawns.entry={x:10,y:12,dir:'up'};const p=destination?.spawns?.[spawn]||{x,y,dir:'down'};m.returnPoint={map:to,x:p.x,y:p.y};}
function zone(m,id,x,y,w,h,terrain,table,chance=.14){m.encounterZones.push({id,x,y,w,h,terrain,table,chance});}
function scatter(m,t,points){for(const [x,y] of points)m.tiles[y][x]=t}

