// Quiet post-game frontier: four unoccupied cities linked by dense rock tunnels.
function frontierCity(id,name,theme,prevTunnel,nextTunnel,homeId){const m=mk(id,name,40,28,TILE.GRASS,theme);border(m,TILE.CLIFF);hline(m,0,14,40,TILE.PATH);vline(m,20,3,22,TILE.PATH);rect(m,4,3,8,5,TILE.FLOWER);rect(m,29,18,7,6,TILE.SOIL);building(m,14,7,12,8,`${name} Empty House`,homeId,'blue');m.spawns.fromPrev={x:2,y:14,dir:'right'};m.spawns.fromNext={x:37,y:14,dir:'left'};m.objects.push({kind:'sign',x:20,y:16,text:`${name.toUpperCase()} · A quiet settlement waiting for new voices.`,solid:true});edgeExit(m,'west',14,prevTunnel,'fromNext',MAP_LABELS[prevTunnel]||prevTunnel);edgeExit(m,'east',14,nextTunnel,'fromPrev',MAP_LABELS[nextTunnel]||nextTunnel);return m}
function rockTunnel(id,name,prev,next,table){const m=mk(id,name,44,26,TILE.FLOOR,'cave');border(m,TILE.WALL);hline(m,0,13,44,TILE.CAVE);rect(m,5,3,9,7,TILE.ROCK);rect(m,18,16,10,7,TILE.ROCK);rect(m,31,3,8,7,TILE.ROCK);m.spawns.fromPrev={x:2,y:13,dir:'right'};m.spawns.fromNext={x:41,y:13,dir:'left'};m.objects.push({kind:'sign',x:22,y:12,text:`${name}: weathered marks point both ways.`,solid:true});zone(m,`${id}Echoes`,2,2,40,22,[TILE.FLOOR,TILE.CAVE],table,.11);edgeExit(m,'west',13,prev,'fromNext',MAP_LABELS[prev]||prev);edgeExit(m,'east',13,next,'fromPrev',MAP_LABELS[next]||next);return m}
