// Road planning pass: roads visually connect useful destinations without making all walkable ground look paved.
function refineUsefulRoads(m){
 const allowed=new Set([TILE.PATH,TILE.DOOR,TILE.BRIDGE,TILE.GRASS,TILE.FLOWER,TILE.SOIL,TILE.SAND,TILE.TALL]),key=(x,y)=>`${x},${y}`,dirs=[[1,0],[-1,0],[0,1],[0,-1]],paths=[];
 for(let y=0;y<m.h;y++)for(let x=0;x<m.w;x++)if(m.tiles[y][x]===TILE.PATH)paths.push([x,y]);if(!paths.length)return;
 const remaining=new Set(paths.map(([x,y])=>key(x,y))),components=[];while(remaining.size){const first=remaining.values().next().value,stack=[first],part=new Set();remaining.delete(first);while(stack.length){const k=stack.pop();part.add(k);const[x,y]=k.split(',').map(Number);for(const[dx,dy]of dirs){const n=key(x+dx,y+dy);if(remaining.delete(n))stack.push(n)}}components.push(part)}
 const network=new Set([...components.sort((a,b)=>b.size-a.size)[0]]),anchors=[],privateDoors=new Set((m.objects||[]).filter(o=>o.kind==='buildingLabel'&&/(home|lodge)/i.test(o.target||'')).map(o=>key(o.doorX,o.y)));for(let y=0;y<m.h;y++)for(let x=0;x<m.w;x++)if(m.tiles[y][x]===TILE.DOOR&&!privateDoors.has(key(x,y)))anchors.push([x,y]);for(const e of m.exits)if(['north','south','east','west'].includes(e.side))anchors.push([e.x,e.y]);
 for(const start of anchors){if(network.has(key(...start)))continue;const queue=[start],prev=new Map([[key(...start),null]]);let found=null;for(let qi=0;qi<queue.length&&!found;qi++){const[x,y]=queue[qi];for(const[dx,dy]of dirs){const nx=x+dx,ny=y+dy,nk=key(nx,ny);if(nx<0||ny<0||nx>=m.w||ny>=m.h||prev.has(nk)||!allowed.has(m.tiles[ny][nx]))continue;prev.set(nk,key(x,y));if(network.has(nk)){found=nk;break}queue.push([nx,ny])}}if(!found)continue;let cur=found;while(cur){const[x,y]=cur.split(',').map(Number);if(![TILE.DOOR,TILE.BRIDGE].includes(m.tiles[y][x]))m.tiles[y][x]=TILE.PATH;network.add(cur);cur=prev.get(cur)}}
 m.roadPlan={mode:'visual-guidance',anchors:anchors.length,privateDoors:[...privateDoors],roadTiles:m.tiles.flat().filter(t=>t===TILE.PATH).length,walkableOffRoad:true};
}
