function addAmbientNpcs(m,count,prefix,includeHealer=false){const candidates=[];for(let y=3;y<m.h-3;y+=3)for(let x=3+(y%2);x<m.w-3;x+=4){if(!PASSABLE.has(m.tiles[y]?.[x]))continue;if(m.exits.some(e=>Math.abs(e.x-x)+Math.abs(e.y-y)<3))continue;if(m.objects.some(o=>o.solid&&Math.abs(o.x-x)+Math.abs(o.y-y)<2))continue;if(m.npcs.some(n=>Math.abs(n.x-x)+Math.abs(n.y-y)<2))continue;candidates.push([x,y])}for(let i=0;i<count&&i<candidates.length;i++){const[x,y]=candidates[(i*7)%candidates.length];m.npcs.push({id:includeHealer&&i===0?'healer':'citizen',spriteRole:['citizen','trainer','seren','vela'][i%4],ambientId:`${prefix}_${i+1}`,x,y,homeX:x,homeY:y,wander:i%3!==2,wanderRadius:3})}}
