 const used=new Set(h.z.table.map(e=>e[0])),pool=Object.values(SPECIES).filter(s=>stageReady(s,h.cfg)&&s.types.some(t=>h.cfg.types.includes(t))&&!used.has(s.id)).sort((a,b)=>((a.dex+h.mapId.length)%17)-((b.dex+h.mapId.length)%17));
 while(h.z.table.length<6&&pool.length){const s=pool.shift();h.z.table.push([s.id,s.sprite.stage===0?10:s.sprite.stage===1?6:3,h.cfg.levels[0],h.cfg.levels[1]])}
