// Defeat respawn overrides. A plain "nearest center" rule sends the player to the
// Resonance Center building; a few story locations instead return them to the middle of
// the town they belong to. Granite Pass (the old lift) is the first of these: losing a
// battle there drops the player in the middle of Brookhaven City.
const DEFEAT_RESPAWNS = Object.freeze({
  granitePass: Object.freeze({map: 'brookhaven', x: 21, y: 15, dir: 'down', name: 'Brookhaven City', why: 'The lift crew carries you back to Brookhaven.'}),
});

/** Where a wipe sends the player: an explicit override first, then the nearest center. */
function defeatRespawn(mapId) {
  const rule = DEFEAT_RESPAWNS[mapId];
  if (rule) {
    const map = MAPS[rule.map];
    const spawn = map?.spawns?.center || {x: rule.x, y: rule.y, dir: rule.dir};
    return {map: rule.map, x: spawn.x ?? rule.x, y: spawn.y ?? rule.y, dir: spawn.dir || rule.dir, name: map?.name || rule.name, why: rule.why};
  }
  return {...nearestCenter(mapId), why: 'You wake up in the nearest Resonance Center.'};
}

function nearestCenter(mapId){const base=MAPS[mapId]?.returnPoint?.map||mapId,centerMap=CENTER_BY_REGION[base]||'fernbrookCenter',center=MAPS[centerMap],spawn=center?.spawns?.entry||{x:10,y:12,dir:'up'};return{map:centerMap,x:spawn.x,y:spawn.y,dir:spawn.dir||'up',name:center?.name||'Fernbrook Resonance Center'}}
// Field trainers live on the routes, not in the cities. Installed before the map table is frozen.
installWildTrainers(MAPS);
function zoneAt(map,x,y){return map.encounterZones?.find(z=>x>=z.x&&x<z.x+z.w&&y>=z.y&&y<z.y+z.h&&z.terrain.includes(map.tiles[y][x]));}

