   if(!n.ai||this.approach?.npc===n||this.conversationNpc===n||this.npcWanders.has(n))continue;
   const st=this.trainerAiState(n);
   if(st.kind!=='spin')continue;
   st.timer+=dt;
   if(st.timer<st.turnMs)continue;
   st.timer=0;
   const order=['down','left','up','right'];
   st.facing=order[(order.indexOf(st.facing)+1)%4];
