 summary(source='primary'){const r=this.decode(this.read(SAVE_KEYS[source]));if(!r.ok)return null;const d=r.data;return{playerName:d.playerName,difficulty:d.difficulty||'medium',map:d.map,badges:d.badges.length,party:d.party.length,chapter:d.story?.chapter||1,playSeconds:Math.floor(d.playSeconds||0),savedAt:r.envelope?.savedAt||d.saveMeta?.savedAt||null,revision:d.saveMeta?.revision||0}}
