 save(reason='autosave'){try{const next=structuredClone(this.data);next.version=SAVE_SCHEMA;next.scene='world';next.saveMeta={...(next.saveMeta||{}),revision:(next.saveMeta?.revision||0)+1,lastReason:reason,savedAt:new Date().toISOString()};const valid=validateState(next);if(!valid.ok)throw new Error(`Validation failed: ${valid.errors.join(', ')}`);const candidate=JSON.stringify(envelope(next,reason));this.storage.setItem(SAVE_KEYS.temp,candidate);const verified=this.decode(this.storage.getItem(SAVE_KEYS.temp));if(!verified.ok)throw new Error(`Temporary save verification failed: ${verified.reason}`);const previous=this.storage.getItem(SAVE_KEYS.primary),previousValid=this.decode(previous);if(previousValid.ok)this.storage.setItem(SAVE_KEYS.backup,previous);this.storage.setItem(SAVE_KEYS.primary,candidate);const committed=this.decode(this.storage.getItem(SAVE_KEYS.primary));if(!committed.ok){if(previousValid.ok)this.storage.setItem(SAVE_KEYS.primary,previous);throw new Error(`Commit verification failed: ${committed.reason}`)}this.storage.removeItem(SAVE_KEYS.temp);this.data=next;this.lastError=null;return this.lastSaveResult={ok:true,reason,revision:next.saveMeta.revision,savedAt:next.saveMeta.savedAt}}catch(error){this.lastError={operation:'save',reason,error:String(error?.message||error)};return this.lastSaveResult={ok:false,reason,error:this.lastError.error}}
 }
 reset(){this.data=freshState();for(const key of Object.values(SAVE_KEYS))this.storage.removeItem(key);this.lastError=null}
