class Input{
 constructor(bindings=null){this.held=new Set();this.pressed=new Set();this.bindings={};this.map={};this.capture=null;this.configure(bindings||DEFAULT_BINDINGS);this.bind()}
 configure(bindings={}){this.bindings={};for(const[action,defaults]of Object.entries(DEFAULT_BINDINGS)){const values=Array.isArray(bindings[action])?bindings[action]:defaults;this.bindings[action]=[...new Set(values.filter(x=>typeof x==='string'))].slice(0,3);if(!this.bindings[action].length)this.bindings[action]=[...defaults]}this.map={};for(const[action,codes]of Object.entries(this.bindings))for(const code of codes)this.map[code]=action}
 rebind(action,code){if(!DEFAULT_BINDINGS[action]||typeof code!=='string')return false;for(const a of Object.keys(this.bindings))this.bindings[a]=this.bindings[a].filter(x=>x!==code);this.bindings[action]=[code,...this.bindings[action]].slice(0,3);this.configure(this.bindings);return true}
 captureNext(action,callback){if(!DEFAULT_BINDINGS[action])return false;this.capture={action,callback};this.held.clear();this.pressed.clear();return true}
 bind(){addEventListener('keydown',e=>{if(this.capture){e.preventDefault();if(['Escape'].includes(e.code)){const cb=this.capture.callback;this.capture=null;cb?.(false,null);return}const{action,callback}=this.capture;this.capture=null;this.rebind(action,e.code);callback?.(true,e.code);return}const k=this.map[e.code];if(!k)return;e.preventDefault();if(!e.repeat&&!this.held.has(k))this.pressed.add(k);this.held.add(k)});addEventListener('keyup',e=>{const k=this.map[e.code];if(k)this.held.delete(k)});const pointerOwners=new Map();document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.draggable=false;const down=e=>{e.preventDefault();e.stopPropagation();if(pointerOwners.has(k))return;pointerOwners.set(k,e.pointerId);b.setPointerCapture?.(e.pointerId);if(!this.held.has(k))this.pressed.add(k);this.held.add(k);b.classList.add('pressed')},up=e=>{e.preventDefault();e.stopPropagation();if(pointerOwners.get(k)!==e.pointerId)return;pointerOwners.delete(k);this.held.delete(k);b.classList.remove('pressed')};b.addEventListener('pointerdown',down,{passive:false});b.addEventListener('pointerup',up,{passive:false});b.addEventListener('pointercancel',up,{passive:false});b.addEventListener('lostpointercapture',up,{passive:false});b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('selectstart',e=>e.preventDefault());b.addEventListener('copy',e=>e.preventDefault())});addEventListener('blur',()=>{pointerOwners.clear();this.held.clear();this.pressed.clear();document.querySelectorAll('[data-key].pressed').forEach(b=>b.classList.remove('pressed'))})}
 consume(k){if(this.pressed.has(k)){this.pressed.delete(k);return true}return false}
 direction(){return['up','down','left','right'].find(k=>this.held.has(k)||this.pressed.has(k))}
 endFrame(){this.pressed.clear()}
}

