  // rather than the Centre's coral, and no shopfront shapes anywhere.
  const roofH=22,bodyTop=top+roofH,bodyBot=y+16,steel='#dfeae9',steelLow='#c3d6d6',teal='#4b9996',tealDeep='#245b61',glass='#bfe4e6';
