  c.fillStyle='#9ad4d4';c.beginPath();c.moveTo(x+4,top+roofH-4);c.lineTo(x+18,top+3);c.lineTo(x+w-18,top+3);c.lineTo(x+w-4,top+roofH-4);c.closePath();c.fill();
  c.fillStyle='rgba(255,255,255,.42)';c.fillRect(x+20,top+5,w-42,2);
  c.fillStyle='rgba(36,91,97,.35)';for(let sx=x+16;sx<x+w-14;sx+=14)c.fillRect(sx,top+6,1,roofH-11);
  c.fillStyle=teal;c.fillRect(x-1,top+roofH-6,w+2,3);
  // radar dish + antenna, slowly turning, with a blinking beacon
  const dishX=x+w-24,dishY=top+2,spin=time/2400;
  c.fillStyle='#8faeae';c.fillRect(dishX+6,dishY+7,3,12);
  c.save();c.translate(dishX+7,dishY+7);c.rotate(Math.sin(spin)*.5);
  c.fillStyle='#e8f2f1';c.beginPath();c.ellipse(0,0,9,5,-.5,0,Math.PI*2);c.fill();
  c.strokeStyle=tealDeep;c.lineWidth=1;c.stroke();c.restore();
  c.fillStyle=Math.floor(time/500)%2?teal:'#b9e8e2';c.fillRect(x+7,top+3,3,3);
  c.fillStyle='#8faeae';c.fillRect(x+8,top+6,1,12);
  // body panels and coolant pipes
  c.fillStyle=steel;c.fillRect(x,bodyTop,w,bodyBot-bodyTop);
  c.fillStyle=steelLow;c.fillRect(x,bodyBot-8,w,8);
  c.fillStyle='rgba(120,150,152,.35)';for(let sy=bodyTop+10;sy<bodyBot-10;sy+=12)c.fillRect(x,sy,w,1);
  c.fillStyle=tealDeep;c.fillRect(x,bodyTop,3,bodyBot-bodyTop);c.fillRect(x+w-3,bodyTop,3,bodyBot-bodyTop);
  c.fillStyle=teal;c.fillRect(x-3,bodyTop-2,w+6,4);
  c.fillStyle='#8faeae';c.fillRect(x+4,bodyTop+4,4,bodyBot-bodyTop-6);
  c.fillStyle='#9fc4c4';c.fillRect(x+4,bodyTop+12,4,3);c.fillRect(x+4,bodyTop+26,4,3);
  // specimen window: a tank of teal light with a drifting silhouette
  const tankX=x+16,tankY=bodyTop+22;
  c.fillStyle=tealDeep;c.fillRect(tankX-2,tankY-2,44,32);
  c.fillStyle='#7fd0cb';c.fillRect(tankX,tankY,40,28);
  c.fillStyle='rgba(255,255,255,.30)';c.fillRect(tankX,tankY,40,5);
  const drift=Math.sin(time/700)*6;
  c.fillStyle='#1f5a5c';c.beginPath();c.ellipse(tankX+20+drift,tankY+17,6,4,0,0,Math.PI*2);c.fill();
  c.fillRect(tankX+24+drift,tankY+15,5,2);
  c.fillStyle='rgba(255,255,255,.6)';c.fillRect(tankX+18+drift,tankY+15,2,1);
  for(let i=0;i<4;i++){const by2=(time/220+i*7)%18;c.fillStyle='rgba(255,255,255,.35)';c.fillRect(tankX+6+i*9,tankY+26-by2,2,2)}
  // sign band across the top of the facade
  const pw=Math.min(w-24,80),px=Math.round(cx-pw/2),py=bodyTop+3;
  c.fillStyle=tealDeep;c.fillRect(px-2,py-2,pw+4,13);
  c.fillStyle='#f4faf8';c.fillRect(px,py,pw,9);
  c.fillStyle=teal;c.fillRect(px,py,pw,2);
  c.font='bold 6px monospace';c.textAlign='center';c.fillStyle=tealDeep;c.fillText('RESONANCE LAB',cx,py+7.5);c.textAlign='left';
