  // Painted arena that adapts to the measured command-band height so sprites, plates and menu never collide.
  const c=this.x,env=v.environment||null,sky=arena?.sky||(v.kind==='gym'?'#594461':env?.sky||'#d7e7bf'),ground=arena?.ground||(v.kind==='gym'?'#72546e':env?.ground||'#93b989'),lip='rgba(255,255,255,.22)';
