     g.fillStyle='rgba(6,26,16,.07)';
     for(let y=horizon+10;y<240;y+=8){const offset=((y-horizon)/8)%2?6:0;for(let x=offset;x<320;x+=12)g.fillRect(x,y,3,2)}
