 recordAttackResidue(vis,p,to,time){const key=`${vis.side}:${vis.move}:${vis.hpFrom}:${vis.hpTo}`;if(key===this.lastResidueKey)return;this.lastResidueKey=key;this.attackResidues.push({type:vis.moveType,tox:['rootsnare','briarrush','oldwoodoath'].includes(vis.move)||vis.inflicted==='poison',x:to.x,y:to.y,born:time,tier:p.tier});this.attackResidues=this.attackResidues.slice(-4)}
 drawAttackResidues(time,reduced){const c=this.x;this.attackResidues=this.attackResidues.filter(r=>time-r.born<(reduced?700:2100));for(const r of this.attackResidues){const q=(time-r.born)/(reduced?700:2100),a=(1-q)*.42;c.save();c.globalAlpha=a;c.fillStyle=r.tox?'#843c9b':TYPE_COLORS[r.type]||'#fff';if(r.type==='Tide'||r.tox){c.beginPath();c.ellipse(r.x,r.y+21,22+r.tier*7,4+r.tier*2,0,0,Math.PI*2);c.fill();if(r.tox)for(let i=0;i<5;i++){c.beginPath();c.arc(r.x-14+i*7,r.y+15-Math.sin(time/180+i)*5,2,0,Math.PI*2);c.fill()}}else if(r.type==='Ember'){for(let i=0;i<7;i++)c.fillRect(r.x-25+i*8,r.y+15-(i%3)*3,5,3)}else if(r.type==='Grove'){for(let i=0;i<8;i++)c.fillRect(r.x-28+i*8,r.y+16-(i%2)*3,5,2)}else if(r.type==='Stone'){c.strokeStyle=TYPE_COLORS[r.type]||'#9b8169';c.beginPath();c.moveTo(r.x-30,r.y+20);c.lineTo(r.x-8,r.y+12);c.lineTo(r.x,r.y+21);c.lineTo(r.x+19,r.y+13);c.lineTo(r.x+34,r.y+20);c.stroke()}else if(r.type==='Frost')c.fillRect(r.x-40,r.y+17,80,4);else{c.strokeStyle=TYPE_COLORS[r.type]||'#fff';c.beginPath();c.arc(r.x,r.y,12+r.tier*8+q*12,0,Math.PI*2);c.stroke()}c.restore()}}
 supportCinematics(vis,q,time,x,y,reduced){const c=this.x,color=TYPE_COLORS[vis.moveType]||'#f2d05c';c.save();c.globalCompositeOperation='screen';if(vis.move==='mendnote'){for(let i=0;i<(reduced?6:14);i++){const a=i*2.399+time/260,r=8+q*(12+i*2);c.globalAlpha=.25+(i%4)*.13;c.fillStyle=i%3?color:'#fff';const px=x+Math.cos(a)*r,py=y-Math.sin(a)*r*.7-q*25;c.beginPath();c.arc(px,py,2,0,Math.PI*2);c.fill();if(i%4===0)c.fillRect(px+2,py-6,1,7)}for(let i=0;i<3;i++){c.strokeStyle=i%2?color:'#fff';c.globalAlpha=.5-q*.2;c.beginPath();c.arc(x,y,9+q*(18+i*12),0,Math.PI*2);c.stroke()}}else if(vis.move==='guardtone'){c.translate(x,y);c.strokeStyle=color;c.lineWidth=2;for(let k=0;k<3;k++){const r=13+k*9+Math.sin(time/140+k)*3;c.globalAlpha=.65-k*.14;c.beginPath();for(let i=0;i<6;i++){const a=Math.PI/3*i-Math.PI/2,px=Math.cos(a)*r,py=Math.sin(a)*r;i?c.lineTo(px,py):c.moveTo(px,py)}c.closePath();c.stroke()}c.fillStyle='#fff';c.globalAlpha=.35;c.fillRect(-2,-22,4,44)}c.restore()}
 moveProfile(id){const groups={contact:['coaltap','leaftap','staticnudge','gleamdot','dusktouch','tackle','struggle','scalepulse','chitintap','wisptouch'],charge:['cinderpounce','rushingwake','briarrush','arcdash','resolutebash','colonyrush','steadycadence'],pierce:['dewdart','draftpeck','faultjab','chillpin','auroralance','toxinpin','frostaria','prismcantata'],spiral:['skyspiral','wingflurry','hiverefrain'],claw:['glacierclaw','astraltalon','phantomclaw','windwardchant'],bite:['umbralfang','pyreanthem','voltrefrain'],lob:['graveltoss','elderverse'],beam:['flicker','humbolt','prismwink','quickstep','runebreath'],wave:['ripple','crosswind','vipertorrent','soulcurrent','venomantiphon'],bind:['rootsnare','rimeveil','gloomfold','acidveil','umbradirge','depthlitany'],storm:['thunderlattice'],slam:['basaltcrash','echobreak','monolithverse','canopyrequiem'],ritual:['calderaroar','delugecrown','oldwoodoath','tempestchoir','mountainverdict','whiteoutbell','dawnchorus','nightfallhymn','elderstardescent','miasmacrown','myriadeclipse','beyondbell','spiritthrenody']};const move=MOVES[id]||{};let family=move.visualFamily||'orb';if(!move.visualFamily)for(const[k,list]of Object.entries(groups))if(list.includes(id)){family=k;break}const tier=(move.power||0)>=27?3:(move.power||0)>=19?2:1,variant=[...String(id)].reduce((n,ch)=>n+ch.charCodeAt(0),0)%5,quick=QUICK_STRIKES.includes(id),plan=planFor(id,move);return{id,family,tier,variant,move,quick,plan}}
 attackPoint(profile,q,time,from,to){const t=this.attackTravel(q),dx=to.x-from.x,dy=to.y-from.y;if(profile.family==='lob')return{x:from.x+dx*t,y:from.y+dy*t-Math.sin(t*Math.PI)*(48+profile.variant*3)};if(profile.family==='spiral'){const a=t*Math.PI*4+profile.variant,amp=(1-t)*18;return{x:from.x+dx*t+Math.cos(a)*amp,y:from.y+dy*t+Math.sin(a)*amp}}if(['ritual','storm','bind','slam','claw','bite','contact'].includes(profile.family))return{x:to.x,y:to.y};if(profile.family==='wave')return{x:from.x+dx*t,y:from.y+dy*t+Math.sin(t*Math.PI*3)*5};return{x:from.x+dx*t,y:from.y+dy*t}}
