  this.mode='title';this.collectionTab='party';this.selectedCreature=null;this.pendingEvolution=null;this.pendingEvolutionQueue=[];this.starterReveal=null;this.battleContext=null;this.battleUiSerial=-1;this.battleMenuMode='commands';this.battleEndAt=0;this.last=performance.now();
  const ids=['titleScreen','openingScene','skipOpeningBtn','difficultyScreen','easyDifficultyBtn','mediumDifficultyBtn','hardDifficultyBtn','cancelDifficultyBtn','continueBtn','newBtn','titleSettingsBtn','creditsBtn','creditsScreen','closeCreditsBtn','titleStatus','recoverBtn','pauseScreen','pauseBtn','resumeBtn','pausePlayer','pauseProgress','pausePartyBtn','pauseDexBtn','pauseBagBtn','pauseMapBtn','pauseJournalBtn','pauseSaveBtn','pauseSettingsBtn','pauseTitleBtn','mobileControls','mobileActionLabel','mobileCancelLabel','saveBtn','mapBtn','partyBtn','profileBtn','bagBtn','journalBtn','dexBtn','settingsBtn','animBtn','muteBtn','dialogue','speaker','dialogueText','choices','battleMenu','battleMessage','battleActions','locationLabel','questLabel','partyLabel','toast','locationBanner','areaMap','mapNodes','mapGuide','closeMapBtn','collectionScreen','collectionTitle','collectionList','collectionDetail','partyTab','storageTab','closeCollectionBtn','dexScreen','dexGrid','dexDetail','dexCount','closeDexBtn','evolutionUI','evolutionText','cancelEvolutionBtn','bagScreen','bagCapacity','bagTabs','bagList','bagDetail','closeBagBtn','shopScreen','shopTitle','shopList','shopDetail','buyTab','sellTab','closeShopBtn','healingUI','healingText','journalScreen','chapterTitle','questList','questDetail','closeJournalBtn','profileScreen','profileTitle','badgeGrid','profileDetail','closeProfileBtn','settingsScreen','closeSettingsBtn','infoBtn','masterVolume','masterValue','musicVolume','musicValue','sfxVolume','sfxValue','ambienceVolume','ambienceValue','musicMuted','sfxMuted','animationSpeed','textSpeed','reducedMotion','muteAll','bindingList','bootOverlay','bootText','bootBar'];this.refs=Object.fromEntries(ids.map(id=>[id,document.getElementById(id)]));this.refs.shellEl=document.querySelector('.shell');this.refs.frameEl=document.querySelector('.game-frame');this.battleBandVirtual=64;this.fitPending=false;this.renderer.battleBand=64;requestAnimationFrame(()=>this.scheduleFit());const r