  this.applySettings();this.story=new StorySystem(this.store,{openDialogue:d=>this.openDialogueData(d),startStoryBattle:(a,c)=>this.startStoryBattle(a,c),giveItem:(id,q)=>this.inventory.add(id,q),toast:t=>this.toast(t),busy:()=>this.mode!=='world'||this.dialogue.active});this.bind();this.buildAreaMap();this.updateTitleScreen();this.prepareBoot();requestAnimationFrame(t=>this.loop(t));
