 renderDialogue(){const r=this.refs;if(!this.dialogue.active){r.dialogue.classList.add('hidden');return}const v=this.dialogue.view();r.dialogue.classList.remove('hidden');r.speaker.textContent=v.speaker;const speakerColors={'Dr. Vela':'#65bdb9',Orin:'#e56f4f','Champion Seren':'#e4bd59','Nurse Luma':'#e58da2','Null Choir':'#8d65a3',Vale:'#9a6678'};r.dialogue.style.setProperty('--speaker-color',speakerColors[v.speaker]||'#8ce0c1');r.dialogue.dataset.portrait=(v.speaker||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();const portraitNames={Mara:8,Neris:9,Kade:10,Siva:11,Oren:12,Liora:13,Bram:14,Astra:15},portrait=/Vela/i.test(v.speaker)?0:/Orin/i.test(v.speaker)?1:/Seren/i.test(v.speaker)?2:/Nurse|Luma/i.test(v.speaker)?3:/Vale/i.test(v.speaker)?4:/Coda/i.test(v.speaker)?16:/Iona/i.test(v.speaker)?17:/Choir/i.test(v.speaker)?5:portraitNames[Object.keys(portraitNames).find(n=>v.speaker.includes(n))]??(/Leader|Conductor/i.test(v.speaker)?8:6),emotion=/sorry|lost|hurt|afraid|failed/i.test(v.text)?2:/!|fight|battle|ready|must/i.test(v.text)?3:/thank|welcome|glad|wonderful/i.test(v.text)?1:0;r.dialogue.style.setProperty('--portrait-index',portrait);r.dialogue.style.setProperty('--portrait-emotion',emotion);r.dialogueText.textContent=v.text;r.dialogueText.classList.toggle('typing',v.typing);r.dialogue.querySelector('.advance').style.display=v.typing||v.choices?'none':'block';r.choices.innerHTML='';if(v.choices)v.choices.forEach(ch=>{const b=document.createElement('button');b.className='choice';b.textContent=ch.label;b.onclick=()=>{this.dialogue.choose(ch.value);this.renderDialogue()};r.choices.appendChild(b)})}
