 onMapChanged(){this.renderer.beginMapTransition();this.audio.setScene(this.worldAudioScene());if(this.store.data.map==='lab'&&!this.store.data.flags.starter)this.store.data.quest.stage=Math.max(1,this.store.data.quest.stage);const p=this.store.data.player;p.spawn={map:this.store.data.map,x:p.x,y:p.y,dir:p.dir};this.refreshHud();this.showLocation();this.autosave('map-transition');this.story.onMapEnter(this.store.data.map)}
