 renderShopDetail(id){const d=ITEMS[id],buy=this.shopMode==='buy',r=this.refs.shopDetail,stock=this.inventory.ensureShop(this.shopId);r.innerHTML=`<h3>${d.name}</h3><p>${d.description}</p><p class="money">${buy?d.buyPrice:d.sellPrice} chimes each</p><p>${buy?`Stock: ${stock[id]||0}`:`In bag: ${this.inventory.quantity(id)}`}</p><div class="detail-actions"></div>`;const a=r.querySelector('.detail-actions');for(const qty of[1,5]){const b=document.createElement('button');b.textContent=`${buy?'Buy':'Sell'} ${qty}`;b.onclick=()=>{if(buy&&!confirm(`Buy ${qty} ${d.name} for ${d.buyPrice*qty} chimes?`))return;if(!buy&&!confirm(`Sell ${qty} ${d.name} for ${d.sellPrice*qty} chimes?`))return;const result=buy?this.inventory.buy(this.shopId,id,qty):this.inventory.sell(this.shopId,id,qty);if(!result.ok)return this.toast(this.itemReason(result.reason));this.store.save();this.toast(buy?`Purchased ${qty} ${d.name}`:`Received ${result.gain} chimes`);this.renderShop()};a.appendChild(b)}}
 itemReason(reason){return({"invalid-item":'Invalid item.',"not-owned":'You do not have that item.',"full-hp":'That creature already has full HP.',"max-level":'That creature is already level 60.',"wrong-condition":'That remedy does not match the condition.',"invalid-target":'Choose a conscious creature.',"not-usable":'That item cannot be used.',"battle-capture-only":'Use capture devices in wild battles.',"insufficient-money":'Not enough chimes.',"insufficient-stock":'The shop lacks that quantity.',"inventory-full":'The bag is full.',"stack-full":'That item stack is full.',"not-for-sale":'That item is not sold here.',"not-sellable":'That item cannot be sold.',"insufficient-quantity":'You do not have enough.',"storage-full":'Creature storage is full.'})[reason]||'That action is not available.'}
 startHealing(){if(this.mode!=='world')return;this.mode='healing';this.healingEndAt=performance.now()+this.battle.duration(1300);this.refs.healingUI.classList.remove('hidden');this.audio.sfx('heal')}
